# R-tree: 先按数据分组，再给每组画最小外接矩形 MBR
function build_rtree(objects):
  groups = cluster_nearby_objects(objects)
  leaves = []
  for group in groups:
    rect = bounding_rectangle(group)  # minX,minY,maxX,maxY
    leaves.append(Node(bounds=rect, children=group))
  return Node(bounds=bounding_rectangle(leaves), children=leaves)

